-- Inventory and POS for the school shop. Apply after the role-model migrations.
create table if not exists public.inventory_products (id uuid primary key default gen_random_uuid(), name text not null, sku text unique, category text, selling_price numeric(12,2) not null check (selling_price >= 0), quantity_on_hand integer not null default 0 check (quantity_on_hand >= 0), reorder_level integer not null default 5 check (reorder_level >= 0), active boolean not null default true, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.pos_sales (id uuid primary key default gen_random_uuid(), receipt_number text unique not null default ('RLC-' || to_char(now(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 6)), customer_name text, payment_method text not null check (payment_method in ('cash','ecocash','swipe','transfer')), total numeric(12,2) not null check (total >= 0), sold_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.pos_sale_items (id uuid primary key default gen_random_uuid(), sale_id uuid not null references public.pos_sales(id) on delete cascade, product_id uuid not null references public.inventory_products(id), product_name text not null, unit_price numeric(12,2) not null, quantity integer not null check (quantity > 0), line_total numeric(12,2) not null);
alter table public.inventory_products enable row level security; alter table public.pos_sales enable row level security; alter table public.pos_sale_items enable row level security;
create policy "Operational staff read inventory" on public.inventory_products for select to authenticated using (public.is_admin() or public.is_accountant()); create policy "Admins manage inventory" on public.inventory_products for all to authenticated using (public.is_admin()) with check (public.is_admin()); create policy "Operational staff read sales" on public.pos_sales for select to authenticated using (public.is_admin() or public.is_accountant()); create policy "Operational staff read sale items" on public.pos_sale_items for select to authenticated using (public.is_admin() or public.is_accountant());
create or replace function public.complete_pos_sale(p_items jsonb, p_payment_method text, p_customer_name text default null) returns public.pos_sales language plpgsql security definer set search_path = public as $$ declare item jsonb; product public.inventory_products; sale public.pos_sales; total_amount numeric(12,2) := 0; requested_quantity integer; begin if not (public.is_admin() or public.is_accountant()) then raise exception 'You are not allowed to complete POS sales'; end if; if jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then raise exception 'Add at least one item to the sale'; end if; for item in select * from jsonb_array_elements(p_items) loop requested_quantity := (item->>'quantity')::integer; select * into product from public.inventory_products where id = (item->>'product_id')::uuid and active = true for update; if not found then raise exception 'A selected product is unavailable'; end if; if requested_quantity < 1 or product.quantity_on_hand < requested_quantity then raise exception 'Insufficient stock for %', product.name; end if; total_amount := total_amount + product.selling_price * requested_quantity; end loop; insert into public.pos_sales(customer_name, payment_method, total, sold_by) values (nullif(trim(p_customer_name), ''), p_payment_method, total_amount, auth.uid()) returning * into sale; for item in select * from jsonb_array_elements(p_items) loop requested_quantity := (item->>'quantity')::integer; select * into product from public.inventory_products where id = (item->>'product_id')::uuid for update; update public.inventory_products set quantity_on_hand = quantity_on_hand - requested_quantity, updated_at = now() where id = product.id; insert into public.pos_sale_items(sale_id, product_id, product_name, unit_price, quantity, line_total) values (sale.id, product.id, product.name, product.selling_price, requested_quantity, product.selling_price * requested_quantity); end loop; return sale; end; $$;
revoke all on function public.complete_pos_sale(jsonb, text, text) from public; grant execute on function public.complete_pos_sale(jsonb, text, text) to authenticated;
